window.ATLAS_HELP_INDEX = [
{"page": "index", "anchor": "", "title": "Overview", "heading": "Overview", "text": "This guide is for the people who use atlas-duck: users and, in server mode, admins and auditors.", "href": "index.html"},
{"page": "index", "anchor": "what-is-atlas-duck", "title": "Overview", "heading": "What atlas-duck is", "text": "atlas-duck lets AI agents read Jira and Confluence Data Center and propose writes that you approve. Every action is recorded in a tamper-evident audit chain. There are two ways to run it: Desktop mode", "href": "index.html#what-is-atlas-duck"},
{"page": "index", "anchor": "how-it-works", "title": "Overview", "heading": "How a request flows", "text": "An agent asks atlas-duck for something, for example to read a Jira issue or to change one. The request appears in your approvals. Nothing reaches the instance yet. You decide. You approve a write, rel", "href": "index.html#how-it-works"},
{"page": "index", "anchor": "where-to-start", "title": "Overview", "heading": "Where to start", "text": "Getting started (desktop) installs atlas-duck and walks through the first start. Instances and tokens connects your Jira and Confluence servers. Agents (desktop) shows how an agent reaches atlas-duck.", "href": "index.html#where-to-start"},
{"page": "getting-started-desktop", "anchor": "", "title": "Getting started (desktop)", "heading": "Getting started (desktop)", "text": "", "href": "getting-started-desktop.html"},
{"page": "getting-started-desktop", "anchor": "install", "title": "Getting started (desktop)", "heading": "Install", "text": "atlas-duck installs three programs side by side: atlas-duck-app (the tray application with the approval windows), atlas-duck (the command line and the MCP server that agents call) and atlas-duck-sandb", "href": "getting-started-desktop.html#install"},
{"page": "getting-started-desktop", "anchor": "first-start", "title": "Getting started (desktop)", "heading": "First start and setup", "text": "The first time atlas-duck starts, the setup window leads you through these steps in order. Until setup is finished, requests from agents are refused and the window shows \"Setup required\" with the numb", "href": "getting-started-desktop.html#first-start"},
{"page": "getting-started-desktop", "anchor": "connect-instance", "title": "Getting started (desktop)", "heading": "Connect an instance", "text": "An instance is one Jira or Confluence Data Center server. In desktop mode you define your own, either in the setup window or later in Settings under \"Add an instance\". Enter an alias, the product (Jir", "href": "getting-started-desktop.html#connect-instance"},
{"page": "getting-started-desktop", "anchor": "tray", "title": "Getting started (desktop)", "heading": "The tray menu", "text": "atlas-duck runs in the system tray. Closing a window only hides it. The tooltip shows how many requests are pending (\"atlas-duck: N pending\"). The menu has these entries: Entry What it does Open appro", "href": "getting-started-desktop.html#tray"},
{"page": "instances-and-tokens", "anchor": "", "title": "Instances and tokens", "heading": "Instances and tokens", "text": "", "href": "instances-and-tokens.html"},
{"page": "instances-and-tokens", "anchor": "instances", "title": "Instances and tokens", "heading": "Instances", "text": "An instance is one Jira or Confluence Data Center server that atlas-duck talks to. It is known by an alias, for example the short name of the server. In desktop mode you define your own instances. Set", "href": "instances-and-tokens.html#instances"},
{"page": "instances-and-tokens", "anchor": "add-instance", "title": "Instances and tokens", "heading": "Add an instance", "text": "Open Settings, \"Add an instance\" (the setup window has the same form), and fill in: Alias and Product (Jira or Confluence). Base URL (https, with the context path). atlas-duck requires https. Proxy, a", "href": "instances-and-tokens.html#add-instance"},
{"page": "instances-and-tokens", "anchor": "tokens", "title": "Instances and tokens", "heading": "Tokens", "text": "atlas-duck always acts as you, with your own personal access token (PAT), never with a shared service account. Create the token in Jira or Confluence (Profile → Personal Access Tokens) and give it onl", "href": "instances-and-tokens.html#tokens"},
{"page": "instances-and-tokens", "anchor": "token-storage", "title": "Instances and tokens", "heading": "Where tokens are stored", "text": "Your tokens are kept in the operating system keychain of this computer. atlas-duck never shows a stored token again. Backups never contain tokens: after a restore, every instance needs its token again", "href": "instances-and-tokens.html#token-storage"},
{"page": "instances-and-tokens", "anchor": "credential-window", "title": "Instances and tokens", "heading": "The credential window", "text": "Tokens and passphrases are typed in a separate window, the credential window, and nowhere else. For a token it is titled \"Add token\" or \"Replace token\". Before you type, it shows the Instance, the Pro", "href": "instances-and-tokens.html#credential-window"},
{"page": "agents-desktop", "anchor": "", "title": "Agents (desktop)", "heading": "Agents (desktop)", "text": "", "href": "agents-desktop.html"},
{"page": "agents-desktop", "anchor": "launcher", "title": "Agents (desktop)", "heading": "Start an agent", "text": "An agent reaches atlas-duck through the atlas-duck command. It does not need a password or a token of its own. It talks to the running desktop app on your computer, and every request lands in your app", "href": "agents-desktop.html#launcher"},
{"page": "agents-desktop", "anchor": "cli", "title": "Agents (desktop)", "heading": "The command line", "text": "atlas-duck [options] \u003ccommand> Options for every command: Option Meaning --agent NAME The agent's name; also ATLAS_DUCK_AGENT. --reason TEXT Why the agent asks. You read it in the queue. --timeout SEC", "href": "agents-desktop.html#cli"},
{"page": "agents-desktop", "anchor": "mcp", "title": "Agents (desktop)", "heading": "MCP clients", "text": "Many agents speak MCP. Add atlas-duck to the agent's MCP settings as a program that starts over standard input and output: atlas-duck mcp [--tools full|generic] [--instance ALIAS] [--agent NAME] Only", "href": "agents-desktop.html#mcp"},
{"page": "agents-desktop", "anchor": "envelope", "title": "Agents (desktop)", "heading": "The response format", "text": "Every command prints one JSON object on standard output, the envelope. Its keys are always the same: Key Content request_id The id of the request. op_id The operation. instance The instance. status pe", "href": "agents-desktop.html#envelope"},
{"page": "approvals", "anchor": "", "title": "Approvals", "heading": "Approvals", "text": "", "href": "approvals.html"},
{"page": "approvals", "anchor": "queue", "title": "Approvals", "heading": "The approval queue", "text": "Nothing an agent asks for leaves atlas-duck without your decision. Every request that needs one waits in the queue under \"Pending approvals\". When nothing waits, the list says \"No pending requests\". T", "href": "approvals.html#queue"},
{"page": "approvals", "anchor": "reading-a-request", "title": "Approvals", "heading": "Reading a request", "text": "Opening a request fills the detail pane, \"Request detail\". At first the pane only offers \"Open preview\". Opening the preview is what makes a decision possible: you decide on what you have seen. The pa", "href": "approvals.html#reading-a-request"},
{"page": "approvals", "anchor": "approve-or-deny", "title": "Approvals", "heading": "Approve, release or deny", "text": "The buttons depend on the class of the request: Request Buttons What happens Write \"Approve\" atlas-duck executes the change. Read \"Release\" The data the instance returned is handed to the agent. Scrip", "href": "approvals.html#approve-or-deny"},
{"page": "approvals", "anchor": "edit-and-redact", "title": "Approvals", "heading": "Editing and redacting", "text": "You can change what is executed, or hold back parts of what is released. Both create a new revision of the request. atlas-duck never changes the old revision. Edit a write. \"Edit before approving\" sho", "href": "approvals.html#edit-and-redact"},
{"page": "approvals", "anchor": "batch-decisions", "title": "Approvals", "heading": "Batch decisions", "text": "When many similar requests wait, decide them together. Select the rows, or use \"select all from session\", and the \"Batch decision\" bar appears. \"Approve or release N selected\" first shows what will ha", "href": "approvals.html#batch-decisions"},
{"page": "approvals", "anchor": "needs-attention", "title": "Approvals", "heading": "Needs attention", "text": "Below the queue, \"Recently decided (24 h)\" lists what was decided in the last day. Entries under \"Needs attention\" are approved writes that did not end well: the write failed, ended with an unknown ou", "href": "approvals.html#needs-attention"},
{"page": "approvals", "anchor": "unverified-text", "title": "Approvals", "heading": "Unverified text", "text": "Everything an agent writes is untrusted: the reason, the agent name and the parameters. atlas-duck therefore marks what it could not check. \"unverified\" marks a text that was written by the agent and", "href": "approvals.html#unverified-text"},
{"page": "scripts", "anchor": "", "title": "Scripts", "heading": "Scripts", "text": "", "href": "scripts.html"},
{"page": "scripts", "anchor": "what-are-scripts", "title": "Scripts", "heading": "What scripts are", "text": "A script lets an agent do many reads in one request. It is JavaScript: the body of async function main(args, atlas). Inside, it calls read operations with atlas.\u003cproduct>.\u003cop>(params), atlas.call, pag", "href": "scripts.html#what-are-scripts"},
{"page": "scripts", "anchor": "running-scripts", "title": "Scripts", "heading": "Running scripts", "text": "An agent submits a script with atlas-duck script run \u003cfile>, or with the script_run tool of the MCP server. See Agents (desktop). To see what is running, open \"Running scripts\" from the header of the", "href": "scripts.html#running-scripts"},
{"page": "scripts", "anchor": "limits", "title": "Scripts", "heading": "Limits and confinement", "text": "Every script runs under limits, so that one script cannot use up your machine or an instance. You set them in Settings under \"Script limits\": Limit Default Script timeout (s) 120 Script heap limit (Mi", "href": "scripts.html#limits"},
{"page": "scripts", "anchor": "stopping", "title": "Scripts", "heading": "Stop a script", "text": "To stop a script, use \"Kill\" in \"Running scripts\". The button changes to \"Stopping…\", and the window answers \"Kill requested\". If the script has already ended, you see \"That script is no longer runnin", "href": "scripts.html#stopping"},
{"page": "audit", "anchor": "", "title": "Audit log", "heading": "Audit log", "text": "", "href": "audit.html"},
{"page": "audit", "anchor": "audit-log", "title": "Audit log", "heading": "What the audit log records", "text": "atlas-duck keeps a record of everything that happens around a request: that it arrived, what you saw, what you decided, what was sent to the instance and what came back, and what the agent received. T", "href": "audit.html#audit-log"},
{"page": "audit", "anchor": "verify", "title": "Audit log", "heading": "Verify the chain", "text": "Verification checks that the chain is complete and unchanged: every record belongs to its predecessor, the payloads match their fingerprints, and the log head matches the copies kept elsewhere. atlas-", "href": "audit.html#verify"},
{"page": "audit", "anchor": "export", "title": "Audit log", "heading": "Export the log", "text": "An export copies records of a time range, with their decrypted payloads, so that someone else can check them, for example an auditor or the compliance owner. The files are readable by anyone who can o", "href": "audit.html#export"},
{"page": "audit", "anchor": "verify-export", "title": "Audit log", "heading": "Check an export with verify-export", "text": "The recipient checks an export with the command atlas-duck verify-export. It needs no access to your computer or server, and it works offline. atlas-duck verify-export \u003cdir> --manifest-sha256 \u003chex> [-", "href": "audit.html#verify-export"},
{"page": "audit", "anchor": "retention", "title": "Audit log", "heading": "Retention and legal hold", "text": "The audit log is not kept forever. The retention period says how long records stay. In Settings, \"Retention and legal hold\" has \"Audit retention (days)\". The default is 100 days and the minimum is 92.", "href": "audit.html#retention"},
{"page": "audit", "anchor": "integrity-incident", "title": "Audit log", "heading": "Integrity incidents", "text": "An integrity incident means that a check found something that should not be. Possible causes range from a harmless one, such as restoring a backup, to tampering. atlas-duck cannot tell which one it is", "href": "audit.html#integrity-incident"},
{"page": "settings", "anchor": "", "title": "Settings", "heading": "Settings", "text": "In desktop mode, Settings is its own window. Besides the topics on this page it holds your instances (Instances and tokens), the limits for requests and scripts, retention and legal hold (Audit log),", "href": "settings.html"},
{"page": "settings", "anchor": "language", "title": "Settings", "heading": "Language", "text": "atlas-duck is available in English and German. The language applies to the windows and pages, notifications and native dialogs, and to this guide. Text that agents read, audit records, logs, the comma", "href": "settings.html#language"},
{"page": "settings", "anchor": "notifications", "title": "Settings", "heading": "Notifications and attention", "text": "\"Attention mode\" in Settings decides what happens when a request needs you: Option What happens Show the window without taking focus The approvals window appears but does not take the keyboard focus.", "href": "settings.html#notifications"},
{"page": "settings", "anchor": "cli-install", "title": "Settings", "heading": "Install the command line", "text": "Agents call the atlas-duck command from a terminal. The section \"Command line\" in Settings tells you whether it is on your PATH (\"The atlas-duck command is on your PATH.\" or \"...is not on your PATH.\")", "href": "settings.html#cli-install"},
{"page": "settings", "anchor": "backup", "title": "Settings", "heading": "Backup and restore", "text": "The section \"Recovery and backup\" in Settings protects your audit log. \"Back up now…\" makes a full backup into a folder you choose. Make one before every upgrade. Backups never contain stored tokens.", "href": "settings.html#backup"},
{"page": "troubleshooting", "anchor": "", "title": "Troubleshooting", "heading": "Troubleshooting", "text": "", "href": "troubleshooting.html"},
{"page": "troubleshooting", "anchor": "cannot-connect", "title": "Troubleshooting", "heading": "An instance cannot be reached", "text": "Symptoms: agents get unreachable, upstream_network or upstream_unavailable; a token check says that the instance cannot be reached (pat/instance_unreachable on the server). First separate two cases. I", "href": "troubleshooting.html#cannot-connect"},
{"page": "troubleshooting", "anchor": "token-rejected", "title": "Troubleshooting", "heading": "A token is rejected", "text": "Symptoms: \"The token was refused by the instance.\", state \"needs token\", agents get needs_token. The token may be mistyped or cut off when you copied it. Paste it again. The token may have expired or", "href": "troubleshooting.html#token-rejected"},
{"page": "troubleshooting", "anchor": "nothing-happens", "title": "Troubleshooting", "heading": "A request stays pending", "text": "A request waits until you decide. It is not stuck, it waits for you. Check: Open the Approvals window and look in \"Pending approvals\". The request may wait there, perhaps below others. If nothing is l", "href": "troubleshooting.html#nothing-happens"},
{"page": "troubleshooting", "anchor": "locked", "title": "Troubleshooting", "heading": "The app is locked", "text": "Symptoms: agents get locked (exit 9); the tray shows \"Waiting for keyring\" or a locked message. This is about the desktop app. The app is locked when it cannot get the key to its audit log. The detail", "href": "troubleshooting.html#locked"},
{"page": "troubleshooting", "anchor": "audit-storage", "title": "Troubleshooting", "heading": "The audit storage is low", "text": "Symptoms: agents get audit_storage_low; a warning shows in the app and in the tray; decisions fail with an audit error. This is about the desktop app; on the server the operator watches the storage. a", "href": "troubleshooting.html#audit-storage"},
{"page": "error-reference", "anchor": "", "title": "Error reference", "heading": "Error reference", "text": "", "href": "error-reference.html"},
{"page": "error-reference", "anchor": "errors-envelope", "title": "Error reference", "heading": "Errors of the command line and agents", "text": "Every failed request of an agent carries an error object with a code, a retryable flag and a message. The code tells you what went wrong. The flag tells the agent whether sending the same request agai", "href": "error-reference.html#errors-envelope"},
{"page": "error-reference", "anchor": "err-usage", "title": "Error reference", "heading": "usage", "text": "The request was not valid: a command, an option or a combination of options that atlas-duck does not know. Nothing was queued. Exit 2, not retryable. Check the command with --help.", "href": "error-reference.html#err-usage"},
{"page": "error-reference", "anchor": "err-validation", "title": "Error reference", "heading": "validation", "text": "The request was well formed but did not pass validation, for example a missing or wrong parameter of an operation. Nothing was queued. Exit 2, not retryable. Look up the operation with ops describe \u003co", "href": "error-reference.html#err-validation"},
{"page": "error-reference", "anchor": "err-markdown-placeholders", "title": "Error reference", "heading": "markdown_placeholders", "text": "The text contains placeholders that cannot be sent as written. When an agent writes a Confluence page or comment in Markdown, atlas-duck refuses a text that still contains placeholders that it put the", "href": "error-reference.html#err-markdown-placeholders"},
{"page": "error-reference", "anchor": "err-op-unsupported-by-instance", "title": "Error reference", "heading": "op_unsupported_by_instance", "text": "This instance does not support the operation, for example because its version is too old. Exit 2, not retryable. Use another operation or another instance, or ask the administrator of the instance.", "href": "error-reference.html#err-op-unsupported-by-instance"},
{"page": "error-reference", "anchor": "err-internal", "title": "Error reference", "heading": "internal", "text": "An internal error occurred in atlas-duck, or in the server. Not retryable. Try again later. If it keeps happening, tell your administrator, and give them the request id and the time.", "href": "error-reference.html#err-internal"},
{"page": "error-reference", "anchor": "err-audit-failure", "title": "Error reference", "heading": "audit_failure", "text": "The audit log could not be written, so nothing was done. atlas-duck never acts without recording it. Exit 1. For reads and scripts the agent may try again; for writes it is not retryable, because the", "href": "error-reference.html#err-audit-failure"},
{"page": "error-reference", "anchor": "err-audit-storage-low", "title": "Error reference", "heading": "audit_storage_low", "text": "The storage for the audit log is almost full. atlas-duck refuses new requests so that the log can always be written. Nothing was queued. Exit 1, retryable. Free disk space on the drive that holds the", "href": "error-reference.html#err-audit-storage-low"},
{"page": "error-reference", "anchor": "err-busy", "title": "Error reference", "heading": "busy", "text": "Another operation is running. Nothing was queued. Exit 11, retryable. Wait for the time that retry_after_s names and try again.", "href": "error-reference.html#err-busy"},
{"page": "error-reference", "anchor": "err-unreachable", "title": "Error reference", "heading": "unreachable", "text": "The command line could not reach the app, so nothing was queued. Exit 5. The details.reason says why: Reason What to do not_running The app is not running. Start it. launch_timeout The app did not sta", "href": "error-reference.html#err-unreachable"},
{"page": "error-reference", "anchor": "err-server-identity", "title": "Error reference", "heading": "server_identity", "text": "The program that answered is not the app that belongs to your user. atlas-duck refuses to talk to it. Exit 5, not retryable. This is a safety check. Make sure that no other program uses the app's conn", "href": "error-reference.html#err-server-identity"},
{"page": "error-reference", "anchor": "err-protocol-mismatch", "title": "Error reference", "heading": "protocol_mismatch", "text": "The command line and the app speak versions of the protocol that do not fit. Exit 5. Update both to the same version and restart the app. Restart the MCP server of the agent as well.", "href": "error-reference.html#err-protocol-mismatch"},
{"page": "error-reference", "anchor": "err-upstream-http", "title": "Error reference", "heading": "upstream_http", "text": "The Jira or Confluence server answered with an error. This code appears when a write failed after you approved it, when you released the error of a read, or when you denied a request and attached the", "href": "error-reference.html#err-upstream-http"},
{"page": "error-reference", "anchor": "err-upstream-network", "title": "Error reference", "heading": "upstream_network", "text": "The connection to the instance failed. Exit 6. When it happened before the request was sent, it is retryable. When it came out of a read and you released it, it is a fixed message without data and not", "href": "error-reference.html#err-upstream-network"},
{"page": "error-reference", "anchor": "err-upstream-unavailable", "title": "Error reference", "heading": "upstream_unavailable", "text": "The instance is not available right now. Exit 6. Reads can be retried later. If the reason is identity_header_missing or identity_header_mismatch, a proxy in front of Jira changes the user header, so", "href": "error-reference.html#err-upstream-unavailable"},
{"page": "error-reference", "anchor": "err-upstream-unknown-outcome", "title": "Error reference", "heading": "upstream_unknown_outcome", "text": "A write was sent, but atlas-duck does not know whether the instance carried it out, for example after a timeout, a server error or a crash. Status outcome_unknown, exit 6, not retryable. Check the tar", "href": "error-reference.html#err-upstream-unknown-outcome"},
{"page": "error-reference", "anchor": "err-result-too-large", "title": "Error reference", "heading": "result_too_large", "text": "The result is too large to return. Exit 6, not retryable. The agent should ask for less: a smaller page, fewer fields, or a narrower search.", "href": "error-reference.html#err-result-too-large"},
{"page": "error-reference", "anchor": "err-needs-token", "title": "Error reference", "heading": "needs_token", "text": "A token is needed for this instance. The token is missing, or the instance has refused it. Exit 9. Add or replace the token, see Instances and tokens and A token is rejected. Agents should not retry i", "href": "error-reference.html#err-needs-token"},
{"page": "error-reference", "anchor": "err-locked", "title": "Error reference", "heading": "locked", "text": "The app is locked: it cannot open its audit log or its keys. Exit 9. The details.reason says why, for example that the keychain is not available yet, that it was lost, or that the keyring lies on a ne", "href": "error-reference.html#err-locked"},
{"page": "error-reference", "anchor": "err-not-configured", "title": "Error reference", "heading": "not_configured", "text": "This instance, or the app, is not set up yet. Exit 9. The details.reason names the gap: the first-run wizard is not finished, no instance exists for the product, an instance uses http:// instead of ht", "href": "error-reference.html#err-not-configured"},
{"page": "error-reference", "anchor": "err-script-syntax", "title": "Error reference", "heading": "script_syntax", "text": "The script has a syntax error. atlas-duck compiles every script on submission and refuses a faulty one. Exit 8, not retryable. Fix the script. See Scripts.", "href": "error-reference.html#err-script-syntax"},
{"page": "error-reference", "anchor": "err-script-limit", "title": "Error reference", "heading": "script_limit", "text": "The script hit a limit and was stopped: time, memory, number of calls, data fetched or size of the result. Exit 8, not retryable. Make the script do less, or raise the limit in Settings, see Limits an", "href": "error-reference.html#err-script-limit"},
{"page": "error-reference", "anchor": "err-sandbox-unavailable", "title": "Error reference", "heading": "sandbox_unavailable", "text": "The script sandbox is not available, so scripts cannot run. Exit 8, not retryable. If the reason is app_upgraded, restart the app and try again. Otherwise the operating system does not allow the confi", "href": "error-reference.html#err-sandbox-unavailable"},
{"page": "error-reference", "anchor": "err-result-evicted", "title": "Error reference", "heading": "result_evicted", "text": "The outcome is known, but the result is no longer stored. Exit 10. For reads and scripts the agent can submit the request again; for a write do not repeat it, because the change was already made.", "href": "error-reference.html#err-result-evicted"},
{"page": "error-reference", "anchor": "err-denied", "title": "Error reference", "heading": "denied", "text": "You denied the request. The message holds your reason. Exit 3, not retryable. The agent should resubmit only when the reason asks for a change. See Approve, release or deny.", "href": "error-reference.html#err-denied"},
{"page": "error-reference", "anchor": "err-resolution-failed", "title": "Error reference", "heading": "resolution_failed", "text": "A name in the request could not be resolved, for example a user, a field or a project that does not exist under that name. Exit 3 when you attached it as a hint to a deny. The details name the paramet", "href": "error-reference.html#err-resolution-failed"},
{"page": "error-reference", "anchor": "err-expired", "title": "Error reference", "heading": "expired", "text": "Nobody decided the request in time. Exit 7, not retryable. Submit again only if you want that.", "href": "error-reference.html#err-expired"},
{"page": "error-reference", "anchor": "err-cancelled", "title": "Error reference", "heading": "cancelled", "text": "The request was cancelled: by the agent (cancel, not retryable), because the app was quit or the system shut down (retryable). Exit 7. Nothing was executed, and a cancelled result never reaches your q", "href": "error-reference.html#err-cancelled"},
{"page": "error-reference", "anchor": "err-abandoned", "title": "Error reference", "heading": "abandoned", "text": "The request was still pending when the app crashed or was killed. Exit 7, retryable. Submit it again. A write that was already approved becomes outcome_unknown instead, see upstream_unknown_outcome.", "href": "error-reference.html#err-abandoned"},
{"page": "error-reference", "anchor": "err-unknown-request", "title": "Error reference", "heading": "unknown_request", "text": "There is no request with this id. Exit 2. Check the id, or find it with requests list.", "href": "error-reference.html#err-unknown-request"},
{"page": "error-reference", "anchor": "err-protocol-error", "title": "Error reference", "heading": "protocol_error", "text": "The app and the command line tool could not agree on a message. Exit 1, not retryable. This usually means that they have different versions. Update both and restart the app.", "href": "error-reference.html#err-protocol-error"},
{"page": "error-reference", "anchor": "errors-decision", "title": "Error reference", "heading": "Errors when deciding", "text": "These errors appear in the Approvals window when a decision cannot be applied. In every case nothing was decided, and the request is as it was.", "href": "error-reference.html#errors-decision"},
{"page": "error-reference", "anchor": "err-stale", "title": "Error reference", "heading": "stale", "text": "The request changed in the meantime, for example it received a new revision. Re-read the queue, open the request again and decide on what you see.", "href": "error-reference.html#err-stale"},
{"page": "error-reference", "anchor": "err-invalid", "title": "Error reference", "heading": "invalid", "text": "The decision is not allowed for this request, for example approving something that cannot be approved, or releasing with a preview that you have not opened. Open the preview first, or decide individua", "href": "error-reference.html#err-invalid"},
{"page": "error-reference", "anchor": "err-edit-rejected", "title": "Error reference", "heading": "edit_rejected", "text": "The edit was refused, for example because it changes the target, is not valid, or is too large. The message names the reason. Correct the field, or deny the request. See Editing and redacting.", "href": "error-reference.html#err-edit-rejected"},
{"page": "error-reference", "anchor": "err-audit", "title": "Error reference", "heading": "audit", "text": "The decision could not be recorded in the audit log, so nothing was done. Check the free space of the audit log, then try again. See The audit storage is low.", "href": "error-reference.html#err-audit"},
{"page": "error-reference", "anchor": "err-batch-rejected", "title": "Error reference", "heading": "batch_rejected", "text": "The batch was rejected and nothing was decided. At least one request did not qualify. The reasons are listed per request, see below and Batch decisions.", "href": "error-reference.html#err-batch-rejected"},
{"page": "error-reference", "anchor": "err-not-decidable", "title": "Error reference", "heading": "not_decidable", "text": "The request is not waiting for a decision. Someone else decided it, it expired, or it was cancelled. Re-read the queue.", "href": "error-reference.html#err-not-decidable"},
{"page": "error-reference", "anchor": "errors-batch", "title": "Error reference", "heading": "Errors in batch decisions", "text": "A batch lists these reasons per request. Remove the request from the batch or decide it individually.", "href": "error-reference.html#errors-batch"},
{"page": "error-reference", "anchor": "err-not-pending", "title": "Error reference", "heading": "not_pending", "text": "The request is no longer pending. It was decided, expired or cancelled in the meantime.", "href": "error-reference.html#err-not-pending"},
{"page": "error-reference", "anchor": "err-target-param-edit", "title": "Error reference", "heading": "target_param_edit", "text": "The target of the request cannot be edited. Decide it individually, or deny it so that the agent asks again with the right target.", "href": "error-reference.html#err-target-param-edit"},
{"page": "error-reference", "anchor": "err-not-opened", "title": "Error reference", "heading": "not_opened", "text": "The preview of the request was not opened. Open the preview of every selected request before you decide as a batch.", "href": "error-reference.html#err-not-opened"},
{"page": "error-reference", "anchor": "err-not-approvable", "title": "Error reference", "heading": "not_approvable", "text": "The request cannot be approved as it is, for example because required fields are missing. Decide it individually.", "href": "error-reference.html#err-not-approvable"},
{"page": "error-reference", "anchor": "err-batch-item-flagged", "title": "Error reference", "heading": "batch_item_flagged", "text": "The request is flagged as a possible duplicate or as a similar request. Look at it and approve it individually.", "href": "error-reference.html#err-batch-item-flagged"}
];
